-- Amarra cada arquivo rastreado e cada objeto. Não torna arquivo canônico.
-- Canônico aqui só o token congelado do design system. O rejeitado não volta.

create table if not exists file_binding (
  path text primary key,
  kind text not null check (kind in ('arquivo', 'objeto', 'token')),
  alvo text not null,
  canonico boolean not null default false,
  anterior_ds boolean not null default false,
  constraint canonico_so_token check (
    canonico = false
    or path in (
      'CE-TOKEN-NAVY',
      'CE-TOKEN-NAVY-MID',
      'CE-TOKEN-NAVY-DEEP',
      'CE-TOKEN-SKY',
      'CE-TOKEN-INK',
      'CE-TOKEN-SLATE',
      'CE-TOKEN-MUTED',
      'CE-TOKEN-CANVAS'
    )
  )
);

create or replace function bind_content_object()
returns trigger
language plpgsql
as $$
begin
  values (new.origin_path, 'objeto', new.slug, false, false)
  on conflict (path) do nothing;
  return new;
end;
$$;

drop trigger if exists content_object_binding on content_object;
create trigger content_object_binding
after insert on content_object
for each row execute function bind_content_object();

values (
  'file_binding',
  'processo',
  'path',
  'Amarração de arquivo, objeto ou token. Arquivo não nasce canônico.',
  'alvo aponta para o lugar; não é chave estrangeira quando o alvo é uma pasta'
)
on conflict (name) do nothing;

on conflict (entity, name) do nothing;

drop trigger if exists layer_guard on file_binding;
create trigger layer_guard
before insert on file_binding
for each row execute function forbid_without_prior_layer();

